contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // single public test entry
    function run(address payable ownerCandidate, address payable recipient, uint256 fund) public payable {
        require(address(this).balance >= fund);
        // Deploy-time: c is already deployed by checker with some owner; we only interact through its interface.
        // First, fund contract c with `fund` wei from this test contract so balances can change.
        if (fund > 0) {
            // send Ether to c using its fallback
            address(c).call{value: fund}("");
        }

        // read before balances
        uint256 beforeC = address(c).balance;
        uint256 beforeRecipient = recipient.balance;

        // determine whether caller equals owner according to c.owner()
        address actualOwner = c.owner();
        bool calledByOwner = (ownerCandidate == actualOwner);

        // Now attempt to call withdrawAll as this contract but acting conceptually with ownerCandidate: we cannot change msg.sender,
        // so we model two scenarios by choosing whether to call withdrawAll (this contract is msg.sender) but we encode the property
        // based on whether this contract equals the owner. To create the two cases, require that ownerCandidate equals address(this) or not.
        // We use ownerCandidate as a selector: if ownerCandidate == address(this) we attempt the call (so it's owner), otherwise we attempt it knowing it will revert.
        bool didRevert;
        if (ownerCandidate == address(this)) {
            // ensure our assumption aligns with contract's actual owner for the intended successful path
            // If actualOwner != address(this), the call should revert; record outcome.
            try c.withdrawAll(recipient) {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        } else {
            // ownerCandidate != address(this): we expect the call to revert unless contract's owner is not enforced.
            try c.withdrawAll(recipient) {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        }

        uint256 afterC = address(c).balance;
        uint256 afterRecipient = recipient.balance;

        // General rule:
        // - If the call did not revert, then all Ether that was in c before is transferred to recipient (c balance becomes zero and recipient increases by that amount).
        // - If the call reverted, balances remain unchanged.
        assert(
            (!didRevert && afterC == 0 && afterRecipient == beforeRecipient + beforeC)
            || (didRevert && afterC == beforeC && afterRecipient == beforeRecipient)
        );
    }

    receive() external payable { }
}

