contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes: owner address for constructing expectations, a recipient, an amount to fund C, and a caller flag
    // callerIsOwner = true means this contract should be treated as owner when calling withdrawAll (owner is c.owner())
    function run(address recipient, uint256 amount, bool callerIsOwner) public payable {
        require(address(this).balance >= amount);

        // Record initial values
        address owner = c.owner();
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // Fund C by sending Ether from this contract
        // Ensure the funding amount equals the provided amount for determinism
        if (amount > 0) {
            // transfer to c via fallback (payable)
            (bool sent,) = address(c).call{value: amount}("");
            // treat failed send as test setup failure
            require(sent);
        }

        // After funding, record balances
        uint256 afterFundC = address(c).balance;
        uint256 afterFundThis = address(this).balance;

        // Now attempt withdrawAll as either the owner or a non-owner
        bool withdrew;
        bool reverted;
        if (callerIsOwner) {
            // This contract must be owner to perform withdraw; if not, the call should revert.
            // Call directly; capture revert via try/catch on external call to c.withdrawAll
            try c.withdrawAll(recipient) {
                reverted = false;
                withdrew = true;
            } catch {
                reverted = true;
                withdrew = false;
            }
        } else {
            // Simulate non-owner call by calling through a low-level call with a different sender is impossible here
            // But since the checker deploys c with owner possibly different, we can still call and observe revert behavior
            try c.withdrawAll(recipient) {
                reverted = false;
                withdrew = true;
            } catch {
                reverted = true;
                withdrew = false;
            }
        }

        // Read final balances
        uint256 finalC = address(c).balance;
        uint256 finalThis = address(this).balance;

        // General rule asserted:
        // - If the call did NOT revert, then finalC == 0 and recipient (if equal to address(this)) received the funds: finalThis == afterFundThis + afterFundC
        // - If the call reverted, balances are unchanged by the attempted withdraw: finalC == afterFundC and finalThis == afterFundThis
        // We cannot directly observe recipient balance unless recipient == address(this), so we express transfer effect via c balance and this contract's balance when recipient==this
        if (!reverted) {
            // successful withdraw: contract C must be emptied
            assert(finalC == 0);
            if (recipient == address(this)) {
                // if recipient is this contract, it should have gained exactly the funds that were in C
                assert(finalThis == afterFundThis + afterFundC);
            }
        } else {
            // reverted: no change to balances
            assert(finalC == afterFundC && finalThis == afterFundThis);
        }
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run funds C with `fundAmount`, then attempts withdrawAll to `recipient`.
    // The call is made from this contract (msg.sender == address(this)).
    function run(address recipient, uint256 fundAmount) public payable {
        require(address(this).balance >= fundAmount);

        // Record balance before funding
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // Fund C by sending Ether to it (state-changing call to address(c))
        if (fundAmount > 0) {
            (bool sent, ) = address(c).call{value: fundAmount}("");
            require(sent);
        }

        // Record balance after funding
        uint256 fundedC = address(c).balance;
        uint256 fundedThis = address(this).balance;

        // Attempt withdrawAll and capture whether it reverted by using low-level call to c.withdrawAll
        // We must perform the state-changing call as a top-level statement.
        bytes memory data = abi.encodeWithSignature("withdrawAll(address)", recipient);
        (bool ok, ) = address(c).call(data);
        bool reverted = !ok;

        // Read final balances
        uint256 finalC = address(c).balance;
        uint256 finalThis = address(this).balance;

        // Single assert expressing the general rule:
        // If call succeeded then finalC == 0; if it reverted then finalC == fundedC.
        assert((!reverted && finalC == 0) || (reverted && finalC == fundedC));
    }

    receive() external payable {}
}

