contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that will be called by checker with arbitrary params
    function run(address sender, address payable recipient, uint256 fundAmount) public payable {
        // ensure this test contract has enough balance to fund C when requested
        require(address(this).balance >= fundAmount);

        // Record initial observable values
        address initialOwner = c.owner();
        uint256 beforeBalance = address(c).balance;

        // If fundAmount > 0, send Ether to c by using its fallback (payable)
        if (fundAmount > 0) {
            // top-level external call that changes c's state (balance)
            c.f{value: fundAmount}();
        }

        // After funding, record new balance
        uint256 fundedBalance = address(c).balance;

        // Attempt withdrawal as if msg.sender is 'sender'. Because in this test
        // the InvMutTest contract is the actual msg.sender for calls to c,
        // we simulate different caller identities by using the known initialOwner
        // check: if 'sender' equals initialOwner then we call withdrawAll (will be allowed),
        // otherwise calling withdrawAll should revert. We cannot actually change msg.sender,
        // so we express the property in terms of whether the InvMutTest's address equals sender.

        bool callReverted;
        // perform the withdrawal attempt (top-level call)
        if (sender == address(this)) {
            // simulate owner call: this contract acts as owner
            // Note: for the proof obligation, we consider both branches based on the parameter
            try c.withdrawAll(recipient) {
                callReverted = false;
            } catch {
                callReverted = true;
            }
        } else {
            // simulate non-owner call: this contract is not equal to 'sender'
            // calling withdrawAll should revert because msg.sender != owner
            try c.withdrawAll(recipient) {
                callReverted = false;
            } catch {
                callReverted = true;
            }
        }

        // Observe final balance and whether recipient (this contract) got funds
        uint256 afterBalance = address(c).balance;

        // The general rule to assert:
        // - If this contract was the owner (sender == address(this)), then the call must not revert
        //   and the contract's balance must have become zero and decreased by fundedBalance.
        // - If this contract was not the owner, then the call must revert and the balance must be unchanged.
        assert(
            (
                sender == address(this) &&
                callReverted == false &&
                afterBalance == 0
            ) || (
                sender != address(this) &&
                callReverted == true &&
                afterBalance == fundedBalance
            )
        );
    }

    // Allow this test contract to receive Ether when recipient == address(this)
    receive() external payable { }
}

