contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking parameters: caller address (as bytes20 to avoid creation), recipient, and an amount to send to c
    function run(address ownerCandidate, address payable recipient, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // The provided C was deployed fresh with some owner; we can observe it via c.owner()
        address currentOwner = c.owner();

        // Fund C by sending Ether from this contract
        // this call changes c's balance
        c.f{value: amount}();

        uint256 beforeBalance = address(c).balance;
        // Decide who will call withdrawAll: either the owner (this contract must act as owner) or a non-owner.
        // We cannot change msg.sender for calls, but the invoker of c.withdrawAll will be this test contract.
        // So we simulate two cases by requiring ownerCandidate equal or not equal to this contract's address:
        // If ownerCandidate == address(this) then this test should be the owner; otherwise it should not be owner.
        bool makeThisOwner = (ownerCandidate == address(this));

        // If we need this contract to be the owner but c.owner() is not, we cannot redeploy c; such inputs are discarded
        // Conversely, if we need this contract to be non-owner but c.owner() equals this contract, discard those inputs.
        if (makeThisOwner) {
            require(currentOwner == address(this));
        } else {
            require(currentOwner != address(this));
        }

        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(c).balance;
        uint256 recipientBalanceAfter = address(recipient).balance;

        // General rule asserted:
        // - If caller (this contract) is owner then withdrawAll must succeed (not revert) and transfer all funds out of c to recipient.
        // - If caller is not owner then withdrawAll must revert and c's balance must be unchanged.
        assert(
            (makeThisOwner && !reverted && afterBalance == 0 && recipientBalanceAfter >= recipientBalanceAfter - 0 /* noop */ && recipientBalanceAfter >= 0) ||
            (!makeThisOwner && reverted && afterBalance == beforeBalance)
        );
    }

    // allow receiving Ether when c.transfer(...) is invoked
    receive() external payable { }
}

