    function run(address ownerCandidate, address payable recipient, uint256 amount) public payable {
        require(address(this).balance >= amount);
        // Deploy-time owner of c is set already; we can observe it
        address initialOwner = c.owner();
        // Fund contract c by sending Ether from this test contract
        // Ensure this contract has enough balance (caller of run must fund this test contract externally)
        (bool sent,) = address(c).call{value: amount}("");
        // call fallback to fund; it's allowed to fail only if amount == 0 and fallback accepts 0 too but call returns true even so
        // Record balances before withdraw attempt
        uint256 balBefore = address(c).balance;
        uint256 recipientBefore = recipient.balance;

        // Try withdrawAll as ownerCandidate: since msg.sender for calls from this contract is this contract itself,
        // we cannot change msg.sender. To test both cases, we branch based on whether ownerCandidate equals initialOwner.
        // If ownerCandidate == initialOwner, we treat this call as owner scenario; else non-owner scenario.

        bool reverted;
        if (ownerCandidate == initialOwner) {
            // owner scenario: make sure invocation should succeed (msg.sender is this contract, which must equal owner)
            // For that, require that this contract is indeed the owner; otherwise this path is not meaningful.
            // We require the test only when this contract equals initialOwner so that the assertion is reachable.
            require(address(this) == initialOwner);
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
            // After successful withdraw by owner, c balance should be zero and recipient increased by balBefore
            if (!reverted) {
                assert(address(c).balance == 0 && recipient.balance == recipientBefore + balBefore);
            } else {
                // if it reverted unexpectedly, this is a failure of the contract; still assert false to flag it
                assert(false);
            }
        } else {
            // non-owner scenario: ensure this contract is not the owner so call should revert
            require(address(this) != initialOwner);
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
